<?php
declare(strict_types=1);
require_once __DIR__ . '/fixtures/ShopAccessFixture.php';
/** Original Blueprint p72/p74/p164/p234: native local gates, never paid-order certification. */
final class OfflineListingOrderLineageTest extends WP_UnitTestCase {
 protected function setUp():void {parent::setUp();DigiForge\Core\Activator::activate();ShopAccessFixture::reset();DigiForge\Core\Settings::protectProduction();add_action('digiforge_log',[DigiForge\Security\Logger::class,'write'],10,4);wp_set_current_user(self::factory()->user->create(['role'=>'administrator']));}
 private function version(string $shop):array {
  $research=new DigiForge\Research\Repository();$source=$research->createSource(['shop_key'=>$shop,'name'=>'Offline lineage source','source_type'=>'manual','environment'=>'sandbox']);self::assertNotWPError($source);$observation=$research->ingest(['source_id'=>$source['id'],'title'=>'Local lifecycle fixture','body'=>'Synthetic local fixture, no marketplace claim.']);self::assertNotWPError($observation);$evidence=$research->addEvidence((int)$observation['id'],['evidence_type'=>'manual_note','value'=>'Offline fixture only.']);self::assertNotWPError($evidence);$candidate=$research->createCandidate(['shop_key'=>$shop,'title'=>'Offline lineage '.$shop]);self::assertNotWPError($candidate);self::assertTrue($research->linkEvidence((int)$candidate['id'],(int)$evidence['id']));self::assertNotWPError($research->review((int)$candidate['id'],'APPROVED','Synthetic fixture review only.'));$opportunity=$research->promote((int)$candidate['id']);self::assertNotWPError($opportunity);
  $products=new DigiForge\ProductFactory\Repository();$family=$products->create('product_family',['opportunity_id'=>$opportunity['id'],'name'=>'Offline family']);self::assertNotWPError($family);$product=$products->create('product',['product_family_id'=>$family['id'],'name'=>'Offline product']);self::assertNotWPError($product);$notes=['spec'=>['listing_title_draft'=>'Offline original local artwork','listing_description_draft'=>'Deterministic synthetic acceptance fixture, not a live sale.','seo_keywords'=>['offline','fixture'],'price_strategy'=>['recommended_etsy_price_usd'=>12],'delivery_selection'=>['selected_language'=>'English']]];$version=$products->create('product_version',['product_id'=>$product['id'],'version_label'=>'offline-v1','notes'=>wp_json_encode($notes)]);self::assertNotWPError($version);self::assertNotWPError($products->transition('product_version',(int)$version['id'],'REVIEW'));self::assertNotWPError($products->transition('product_version',(int)$version['id'],'APPROVED'));return $version;
 }
 public static function shops():array{return [['digital'],['personalized_pod'],['standard_pod'],['jewelry']];}
 /** @dataProvider shops */
 public function testListingAndReceivedOrderCannotCrossShopOwnership(string $shop):void {
  ShopAccessFixture::authorizeActor(get_current_user_id(), ['digital', 'personalized_pod', 'standard_pod', 'jewelry'], ['manage_digiforge', 'manage_digiforge_products', 'manage_digiforge_listings', 'manage_digiforge_orders']);
  $marker='Shop listing '.wp_generate_uuid4();$version=$this->version($shop);$listing=(new DigiForge\Listings\Repository())->createListing(['product_version_id'=>$version['id'],'environment'=>'sandbox','channel'=>'etsy','shop_reference'=>$shop,'title'=>$marker,'description'=>'No live listing','price_amount'=>12,'currency'=>'USD']);self::assertNotWPError($listing);global $wpdb;$now=current_time('mysql',true);self::assertSame(1,$wpdb->insert(DigiForge\Database\Tables::listing_readiness_reviews(),['listing_id'=>$listing['id'],'readiness'=>'{}','readiness_hash'=>hash('sha256','{}'),'created_at'=>$now,'updated_at'=>$now]));$get=$_GET;
  try{foreach(['digital','personalized_pod','standard_pod','jewelry'] as $selected){$_GET=['df_view'=>'listings','df_shop'=>$selected];$html=(new DigiForge\Portal\Portal())->render();if($selected===$shop)self::assertStringContainsString($marker,$html);else self::assertStringNotContainsString($marker,$html);}}finally{$_GET=$get;}
  $orders=new DigiForge\Orders\Repository();foreach(['digital','personalized_pod','standard_pod','jewelry']as $other){$order=$orders->createOrder(['shop_reference'=>$other,'channel'=>'etsy','environment'=>'sandbox']);self::assertNotWPError($order);$line=$orders->addLineItem(['order_id'=>$order['id'],'listing_id'=>$listing['id'],'product_version_id'=>$version['id']]);if($other===$shop){self::assertNotWPError($line);self::assertFalse($orders->readiness((int)$order['id'])['ready']);}else self::assertWPError($line);}
  // Selected-shop product evidence must follow the same stored opportunity lineage.
  foreach(['digital','personalized_pod','standard_pod','jewelry'] as $selected){
   foreach(['products'=>DigiForge\Database\Tables::product_versions()] as $view=>$table){
    $old=$_GET;$_GET=['df_shop'=>$selected];ob_start();try{(new ReflectionMethod(DigiForge\Portal\Portal::class,'panelTable'))->invoke(new DigiForge\Portal\Portal(),'Scoped versions',$table);$html=(string)ob_get_contents();}finally{ob_end_clean();$_GET=$old;}
    $row='<tr><td>'.$version['id'].'</td>';if($selected===$shop)self::assertStringContainsString($row,$html);else self::assertStringNotContainsString($row,$html);
   }
  }
  // Read-only ownership inbox must not expose an ambiguously owned product in two shops.
  self::assertSame(1,$wpdb->insert(DigiForge\Database\Tables::pod_business_mappings(),['business_id'=>1,'store_id'=>1,'product_program_id'=>1,'product_version_id'=>$version['id'],'provider_mapping_id'=>1,'created_at'=>$now,'updated_at'=>$now]));$mappingId=(int)$wpdb->insert_id;$model=new DigiForge\Orders\HumanGateOperationsReadModel();
  foreach(['digital','personalized_pod','standard_pod','jewelry'] as $selected){$items=$model->snapshot(50,$selected)['ownership'];$ids=array_map('intval',array_column($items,'id'));if($selected===$shop)self::assertContains($mappingId,$ids);else self::assertNotContains($mappingId,$ids);}
  $opportunityId=(int)$wpdb->get_var($wpdb->prepare('SELECT family.opportunity_id FROM '.DigiForge\Database\Tables::product_versions().' pv INNER JOIN '.DigiForge\Database\Tables::products().' p ON p.id=pv.product_id INNER JOIN '.DigiForge\Database\Tables::product_families().' family ON family.id=p.product_family_id WHERE pv.id=%d',$version['id']));$other=$shop==='digital'?'personalized_pod':'digital';$conflict=(new DigiForge\Research\Repository())->createCandidate(['shop_key'=>$other,'title'=>'Ambiguous ownership '.wp_generate_uuid4()]);self::assertNotWPError($conflict);self::assertSame(1,$wpdb->update(DigiForge\Database\Tables::research_candidates(),['opportunity_id'=>$opportunityId],['id'=>$conflict['id']]));
  foreach([$shop,$other] as $selected)self::assertNotContains($mappingId,array_map('intval',array_column($model->snapshot(50,$selected)['ownership'],'id')));
  self::assertTrue(DigiForge\Core\Settings::safety_locked());self::assertTrue(DigiForge\Core\Settings::get('stop_all',true));self::assertFalse(DigiForge\Core\Settings::get('automation_armed',false));
 }
 public function testSelectedShopScopesDigitalAndProductionEvidenceBeforeWindow():void {
  ShopAccessFixture::authorizeActor(get_current_user_id(), ['digital', 'personalized_pod', 'standard_pod', 'jewelry'], ['manage_digiforge', 'manage_digiforge_products', 'manage_digiforge_digital', 'manage_digiforge_production']);
  global $wpdb;$table=DigiForge\Database\Tables::class;$digital=new DigiForge\DigitalFactory\Repository();$production=new DigiForge\Production\Repository();$marker='Scoped factory '.wp_generate_uuid4();$rows=[];
  foreach(['digital','personalized_pod'] as $shop){$version=$this->version($shop);$dp=$digital->create('digital_product',['name'=>$marker.' '.$shop,'category'=>'fixture','product_id'=>$version['product_id'],'product_version_id'=>$version['id']]);self::assertNotWPError($dp);
   $file=$digital->create('digital_file',['name'=>'File','file_type'=>'png','digital_product_id'=>$dp['id'],'product_version_id'=>$version['id']]);self::assertNotWPError($file);
   $fv=$digital->create('digital_file_version',['version_label'=>'v1','digital_file_id'=>$file['id']]);self::assertNotWPError($fv);
   $package=$digital->create('digital_package',['name'=>'Package','digital_product_id'=>$dp['id'],'product_version_id'=>$version['id']]);self::assertNotWPError($package);
   $preview=$digital->create('digital_preview',['name'=>'Preview','digital_product_id'=>$dp['id'],'digital_file_id'=>$file['id']]);self::assertNotWPError($preview);
   $template=$digital->create('digital_template',['name'=>'Template','digital_product_id'=>$dp['id'],'digital_file_id'=>$file['id'],'digital_preview_id'=>$preview['id']]);self::assertNotWPError($template);
   $license=$digital->create('digital_license',['name'=>'License','license_type'=>'personal','digital_product_id'=>$dp['id']]);self::assertNotWPError($license);
   $spec=$production->createSpec(['product_version_id'=>$version['id'],'asset_key'=>'scoped','asset_type'=>'image','format'=>'png']);self::assertNotWPError($spec);
   $plan=$production->createPlan(['product_version_id'=>$version['id'],'plan_key'=>'scoped','version_label'=>'v1','channel'=>'digital','production_type'=>'fixture']);self::assertNotWPError($plan);
   $revision=$production->addRevision(['asset_spec_id'=>$spec['id'],'revision_label'=>'v1','storage_reference'=>'local://scope-fixture.png','checksum_sha256'=>hash('sha256','offline read fixture')]);self::assertNotWPError($revision);
   $rows[$shop]=['digital_products'=>$dp['id'],'digital_files'=>$file['id'],'digital_file_versions'=>$fv['id'],'digital_packages'=>$package['id'],'digital_previews'=>$preview['id'],'digital_templates'=>$template['id'],'digital_licenses'=>$license['id'],'asset_specs'=>$spec['id'],'production_plans'=>$plan['id'],'asset_revisions'=>$revision['id']];
   foreach(['spec'=>$spec['id'],'plan'=>$plan['id'],'revision'=>$revision['id']] as $target=>$id){$qa=$production->addQa(['target_type'=>$target,'target_id'=>$id,'check_type'=>'scope_fixture','status'=>'PENDING']);self::assertNotWPError($qa);$rows[$shop]['production_qa'][]=$qa['id'];}
  }
  foreach(['digital','personalized_pod','standard_pod','jewelry'] as $shop){$query=$digital->all('digital_product',1,1,$shop);self::assertTrue($query['query_ok']);if(isset($rows[$shop])){self::assertGreaterThanOrEqual(1,$query['pagination']['total_items']);self::assertCount(1,$query['items']);self::assertSame((int)$rows[$shop]['digital_products'],(int)$query['items'][0]['id']);self::assertSame($marker.' '.$shop,$query['items'][0]['name']);}foreach($query['items']as $item){$owners=$wpdb->get_col($wpdb->prepare('SELECT candidate.score_inputs FROM '.$table::research_candidates().' candidate INNER JOIN '.$table::product_families().' family ON family.opportunity_id=candidate.opportunity_id INNER JOIN '.$table::products().' product ON product.product_family_id=family.id INNER JOIN '.$table::product_versions().' version ON version.product_id=product.id WHERE version.id=%d',(int)$item['product_version_id']));self::assertNotEmpty($owners);foreach($owners as $owner)self::assertSame($shop,json_decode((string)$owner,true)['shop_key']??null);}foreach($rows as $owner=>$owned)if($owner!==$shop)self::assertNotContains((int)$owned['digital_products'],array_map('intval',array_column($query['items'],'id')));
   $get=$_GET;$_GET=['df_shop'=>$shop];try{foreach($rows['digital'] as $entity=>$ids){ob_start();(new ReflectionMethod(DigiForge\Portal\Portal::class,'panelTable'))->invoke(new DigiForge\Portal\Portal(),'Scoped fixture',$table::{$entity}());$html=(string)ob_get_clean();foreach($rows as $owner=>$owned)foreach((array)$owned[$entity] as $id){$needle='<tr><td>'.$id.'</td>';if($owner===$shop)self::assertStringContainsString($needle,$html);else self::assertStringNotContainsString($needle,$html);}}}finally{$_GET=$get;}
  }
 }
 public function testReadinessRechecksCurrentListingOwnership():void {
  $version=$this->version('digital');$listing=(new DigiForge\Listings\Repository())->createListing(['product_version_id'=>$version['id'],'environment'=>'sandbox','channel'=>'etsy','shop_reference'=>'digital','title'=>'Offline current lineage','description'=>'Fixture','price_amount'=>12,'currency'=>'USD']);self::assertNotWPError($listing);$orders=new DigiForge\Orders\Repository();$order=$orders->createOrder(['shop_reference'=>'digital','channel'=>'etsy','environment'=>'sandbox']);self::assertNotWPError($order);self::assertNotWPError($orders->addLineItem(['order_id'=>$order['id'],'listing_id'=>$listing['id'],'product_version_id'=>$version['id']]));self::assertTrue($orders->readiness((int)$order['id'])['checks']['line_items_valid']);
  global $wpdb;foreach(['DIGITAL','digital ','jewelry'] as $drift){self::assertSame(1,$wpdb->update(DigiForge\Database\Tables::listings(),['shop_reference'=>$drift],['id'=>$listing['id']]));self::assertFalse($orders->readiness((int)$order['id'])['checks']['line_items_valid']);}
