   $factory=new DigiForge\Listings\ListingFactory();$key='offline-listing-'.wp_generate_uuid4();$result=$factory->prepare((int)$version['id'],$key);self::assertNotWPError($result);self::assertSame('digital',$result['listing']['shop_reference']);self::assertSame('sandbox',$result['listing']['environment']);self::assertSame('REVIEW_REQUIRED',$result['listing']['state']);self::assertSame($result['listing_id'],$factory->prepare((int)$version['id'],$key)['listing_id']);self::assertFalse($result['draft_package_created']);global $wpdb;self::assertGreaterThan(0,(int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM '.DigiForge\Database\Tables::audit_log().' WHERE object_type=%s AND object_id=%s','listing',(string)$result['listing_id'])));
   self::assertSame('RESERVED_LOCAL_QUANTITY',$result['local_quantity_reservation']['quota_state']);self::assertSame(0.0,(float)$result['local_quantity_reservation']['estimated_cost']);self::assertSame(0.0,(float)$result['local_quantity_reservation']['actual_cost']);$over=$factory->prepare((int)$version['id'],$key.'-over');self::assertWPError($over);self::assertSame('listing_preparation_quota_limit_reached',$over->get_error_code());
   // Original p233: approve exactly reviewed material, and keep Gate 2 prerequisites current.
