   self::assertSame('PENDING',$wpdb->get_var($wpdb->prepare('SELECT decision FROM '.DigiForge\Database\Tables::listing_readiness_reviews().' WHERE id=%d',$review['id'])));
   self::assertSame(1,$wpdb->update(DigiForge\Database\Tables::product_versions(),['state'=>'DRAFT'],['id'=>$version['id']]));self::assertWPError($listings->createReadinessReview((int)$result['listing_id']));
   self::assertSame(1,$wpdb->update(DigiForge\Database\Tables::product_versions(),['state'=>'APPROVED'],['id'=>$version['id']]));
