   self::assertSame(1,$wpdb->update(DigiForge\Database\Tables::listings(),['title'=>'Changed after human review snapshot'],['id'=>$result['listing_id']]));self::assertTrue($listings->readiness((int)$result['listing_id'])['ready']);$this->replaceBundleRevision($production,$spec,$bundle,$path,'r3');self::assertFalse($listings->readiness((int)$result['listing_id'])['ready']);
