 private function customerPackage(DigiForge\Production\Repository $production,array $version,array $plan,string $png):string {
  self::assertTrue(DigiForge\ProductFactory\AssetStorage::ensureProtectedRoot());$reference=DigiForge\ProductFactory\AssetStorage::RELATIVE_ROOT.'/offline-download-'.wp_generate_uuid4().'.zip';$path=trailingslashit(wp_upload_dir()['basedir']).$reference;
  $zip=new ZipArchive();self::assertTrue($zip->open($path,ZipArchive::CREATE|ZipArchive::OVERWRITE));self::assertTrue($zip->addFromString('artifact.png',$png));self::assertTrue($zip->setCompressionName('artifact.png',ZipArchive::CM_STORE));self::assertTrue($zip->setMtimeName('artifact.png',315532800));self::assertTrue($zip->close());
  $spec=$production->createSpec(['product_version_id'=>$version['id'],'asset_key'=>'customer-package','asset_type'=>'product_package','format'=>'zip','content_requirements'=>['group'=>'product','filename'=>'offline-download.zip']]);self::assertNotWPError($spec);self::assertTrue($production->linkAsset((int)$plan['id'],(int)$spec['id']));
  $revision=$production->addRevision(['asset_spec_id'=>$spec['id'],'revision_label'=>'offline-package-v1','storage_reference'=>$reference,'checksum_sha256'=>hash_file('sha256',$path),'mime_type'=>'application/zip','byte_size'=>filesize($path),'provenance'=>['origin'=>'offline_acceptance_fixture']]);self::assertNotWPError($revision);
  self::assertNotWPError($production->addQa(['target_type'=>'revision','target_id'=>$revision['id'],'check_type'=>'stored_zip_fixture','status'=>'PASS','details'=>['fixture_only'=>true,'checksum_sha256'=>hash_file('sha256',$path)]]));foreach(['QA_PASSED','APPROVED'] as $state)self::assertNotWPError($production->transition('revision',(int)$revision['id'],$state));return $path;
 }
 private function portalApprovalControls(int $reviewId):int {
  $get=$_GET;$errors=libxml_use_internal_errors(true);try{$_GET=['df_view'=>'listings','df_shop'=>'digital'];$doc=new DOMDocument();$doc->loadHTML((new DigiForge\Portal\Portal())->render());$nodes=(new DOMXPath($doc))->query('//article[.//input[@name="review_id" and @value="'.$reviewId.'"]]//button[@name="decision" and @value="APPROVED"]');self::assertNotFalse($nodes);return $nodes->length;}finally{$_GET=$get;libxml_clear_errors();libxml_use_internal_errors($errors);}
