  self::assertNotWPError($production->addQa(['target_type'=>'revision','target_id'=>$revision['id'],'check_type'=>'decoded_pixels','status'=>'PASS','details'=>['fixture_only'=>true,'pixel_sha256'=>DigiForge\POD\RasterArtworkCodec::decode($bytes)['pixel_sha256']]]));foreach(['QA_PASSED','APPROVED'] as $state)self::assertNotWPError($production->transition('revision',(int)$revision['id'],$state));self::assertSame('RELEASE_READY',$production->validateBundle((int)$bundle['id'])['state']);
 }
